package com.securebiz.sales.repository;
import com.securebiz.sales.api.ReturnDtos.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.math.*;import java.sql.*;import java.time.*;import java.util.*;
@Repository public class ReturnRepository{private final JdbcClient jdbc;public ReturnRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 public Optional<OrderLock> lockOrder(UUID id){return jdbc.sql("SELECT id,warehouse_id,status,created_by FROM orders WHERE id=:id FOR UPDATE").param("id",id).query((r,n)->new OrderLock(r.getObject("id",UUID.class),r.getObject("warehouse_id",UUID.class),r.getString("status"),r.getObject("created_by",UUID.class))).optional();}
 public List<OrderLine> orderLines(UUID order,List<UUID> ids){return jdbc.sql("""
  SELECT oi.id,oi.product_variant_id,oi.sku,oi.quantity,oi.line_total,
   COALESCE((SELECT sum(ri.quantity) FROM return_items ri JOIN returns ret ON ret.id=ri.return_id WHERE ri.order_item_id=oi.id AND ret.status IN('DRAFT','PENDING_APPROVAL','APPROVED','COMPLETED')),0) returned
  FROM order_items oi WHERE oi.order_id=:order AND oi.id IN(:ids) ORDER BY oi.product_variant_id FOR UPDATE
  """).param("order",order).param("ids",ids).query((r,n)->new OrderLine(r.getObject("id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getString("sku"),r.getBigDecimal("quantity"),r.getBigDecimal("line_total"),r.getBigDecimal("returned"))).list();}
 public ReturnResponse create(UUID id,String number,ReturnRequest req,UUID actor,List<ReturnLineDraft> lines){jdbc.sql("INSERT INTO returns(id,return_number,order_id,reason,created_by) VALUES(:id,:number,:order,:reason,:actor)").param("id",id).param("number",number).param("order",req.orderId()).param("reason",req.reason()).param("actor",actor).update();for(var line:lines)jdbc.sql("INSERT INTO return_items(id,return_id,order_item_id,quantity,disposition,unit_refund,line_refund) VALUES(:id,:ret,:orderItem,:qty,:disposition,:unit,:total)").param("id",UUID.randomUUID()).param("ret",id).param("orderItem",line.orderItemId()).param("qty",line.quantity()).param("disposition",line.disposition()).param("unit",line.unitRefund()).param("total",line.lineRefund()).update();return find(id).orElseThrow();}
 public Optional<ReturnResponse> find(UUID id){return jdbc.sql("SELECT * FROM returns WHERE id=:id").param("id",id).query(this::mapReturn).optional();}
 public List<ReturnResponse> list(int size,long offset){return jdbc.sql("SELECT * FROM returns ORDER BY created_at DESC LIMIT :size OFFSET :offset").param("size",size).param("offset",offset).query(this::mapReturn).list();}
 public long count(){return jdbc.sql("SELECT count(*) FROM returns").query(Long.class).single();}
 public Optional<ReturnLock> lockReturn(UUID id){return jdbc.sql("SELECT id,order_id,status,created_by FROM returns WHERE id=:id FOR UPDATE").param("id",id).query((r,n)->new ReturnLock(r.getObject("id",UUID.class),r.getObject("order_id",UUID.class),r.getString("status"),r.getObject("created_by",UUID.class))).optional();}
 public int transition(UUID id,String from,String to,UUID actor){String approval="COMPLETED".equals(to)?",approved_by=:actor,approved_at=now(),completed_at=now()":"";return jdbc.sql("UPDATE returns SET status=:to,updated_at=now(),version=version+1"+approval+" WHERE id=:id AND status=:from").param("to",to).param("actor",actor).param("id",id).param("from",from).update();}
 public List<ReturnLine> lockReturnLines(UUID id){return jdbc.sql("""
  SELECT ri.id,ri.order_item_id,oi.product_variant_id,oi.sku,ri.quantity,ri.disposition,ri.unit_refund,ri.line_refund
  FROM return_items ri JOIN order_items oi ON oi.id=ri.order_item_id WHERE ri.return_id=:id ORDER BY oi.product_variant_id FOR UPDATE
  """).param("id",id).query((r,n)->new ReturnLine(r.getObject("id",UUID.class),r.getObject("order_item_id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getString("sku"),r.getBigDecimal("quantity"),r.getString("disposition"),r.getBigDecimal("unit_refund"),r.getBigDecimal("line_refund"))).list();}
 public Optional<PaymentLock> lockPayment(UUID order){return jdbc.sql("SELECT id,amount,currency FROM payments WHERE order_id=:order AND status='SUCCEEDED' ORDER BY processed_at LIMIT 1 FOR UPDATE").param("order",order).query((r,n)->new PaymentLock(r.getObject("id",UUID.class),r.getBigDecimal("amount"),r.getString("currency"))).optional();}
 public BigDecimal successfulRefunds(UUID payment){return jdbc.sql("SELECT COALESCE(sum(amount),0) FROM refunds WHERE payment_id=:id AND status='SUCCEEDED'").param("id",payment).query(BigDecimal.class).single();}
 public void createRefund(UUID id,UUID ret,PaymentLock payment,BigDecimal amount,UUID actor){jdbc.sql("INSERT INTO refunds(id,return_id,payment_id,amount,currency,status,idempotency_key,processed_at,created_by) VALUES(:id,:ret,:payment,:amount,:currency,'SUCCEEDED',:key,now(),:actor)").param("id",id).param("ret",ret).param("payment",payment.id()).param("amount",amount).param("currency",payment.currency()).param("key",ret.toString()).param("actor",actor).update();}
 public boolean allOrderQuantityReturned(UUID order){return jdbc.sql("""
  SELECT NOT EXISTS(SELECT 1 FROM order_items oi WHERE oi.order_id=:order AND oi.quantity>
   COALESCE((SELECT sum(ri.quantity) FROM return_items ri JOIN returns r ON r.id=ri.return_id WHERE ri.order_item_id=oi.id AND r.status='COMPLETED'),0))
  """).param("order",order).query(Boolean.class).single();}
 public void updateOrderReturnState(UUID order,boolean full){jdbc.sql("UPDATE orders SET status=:status,updated_at=now(),version=version+1 WHERE id=:id").param("status",full?"RETURNED":"PARTIALLY_RETURNED").param("id",order).update();}
 private ReturnResponse mapReturn(ResultSet r,int n)throws SQLException{UUID id=r.getObject("id",UUID.class);var items=items(id);BigDecimal total=items.stream().map(ReturnItemResponse::lineRefund).reduce(BigDecimal.ZERO,BigDecimal::add);String refund=jdbc.sql("SELECT status FROM refunds WHERE return_id=:id ORDER BY created_at DESC LIMIT 1").param("id",id).query(String.class).optional().orElse(null);return new ReturnResponse(id,r.getString("return_number"),r.getObject("order_id",UUID.class),r.getString("status"),r.getString("reason"),r.getObject("created_by",UUID.class),r.getObject("approved_by",UUID.class),instant(r,"approved_at"),instant(r,"completed_at"),total,refund,items);}
 private List<ReturnItemResponse> items(UUID id){return jdbc.sql("SELECT ri.id,ri.order_item_id,oi.product_variant_id,oi.sku,ri.quantity,ri.disposition,ri.unit_refund,ri.line_refund FROM return_items ri JOIN order_items oi ON oi.id=ri.order_item_id WHERE ri.return_id=:id").param("id",id).query((r,n)->new ReturnItemResponse(r.getObject("id",UUID.class),r.getObject("order_item_id",UUID.class),r.getObject("product_variant_id",UUID.class),r.getString("sku"),r.getBigDecimal("quantity"),r.getString("disposition"),r.getBigDecimal("unit_refund"),r.getBigDecimal("line_refund"))).list();}
 private static Instant instant(ResultSet r,String n)throws SQLException{return r.getTimestamp(n)==null?null:r.getTimestamp(n).toInstant();}
 public record OrderLock(UUID id,UUID warehouse,String status,UUID createdBy){}public record OrderLine(UUID id,UUID variant,String sku,BigDecimal purchased,BigDecimal lineTotal,BigDecimal returned){}public record ReturnLineDraft(UUID orderItemId,BigDecimal quantity,String disposition,BigDecimal unitRefund,BigDecimal lineRefund){}public record ReturnLock(UUID id,UUID orderId,String status,UUID createdBy){}public record ReturnLine(UUID id,UUID orderItemId,UUID variant,String sku,BigDecimal quantity,String disposition,BigDecimal unitRefund,BigDecimal lineRefund){}public record PaymentLock(UUID id,BigDecimal amount,String currency){}
}
